  @doc "The registry schema id, for example `\"graphlaw.capability-registry/1\"`."
  @spec schema() :: String.t()
  def schema, do: @schema

  @doc "The GraphLaw release the registry was generated from."
  @spec graphlaw_version() :: String.t()
  def graphlaw_version, do: @graphlaw_version

  @doc "The GraphLaw ABI version the registry describes."
  @spec abi_version() :: pos_integer()
  def abi_version, do: @abi_version

  @doc "The registry digest literal (`\"sha256:<hex>\"`), the registry's own `registry_sha256`."
  @spec digest() :: String.t()
  def digest, do: @digest

  @doc "The surface digest literal (`\"sha256:<hex>\"`) over ABI version, op names and dialect names."
  @spec surface_digest() :: String.t()
  def surface_digest, do: @surface_digest

  @doc "Wire operation names in registry order."
  @spec names() :: [String.t()]
  def names, do: @names

  @doc "All operations in registry order."
  @spec ops() :: [op()]
  def ops, do: @ops

  @doc "The operation named `name`, or `:error` when the registry has no such operation."
  @spec op(String.t()) :: {:ok, op()} | :error
  def op(name) when is_binary(name), do: Map.fetch(@ops_by_name, name)
  def op(_name), do: :error

  @doc "The typed capability module for the operation named `name`, or `:error`."
  @spec module_for(String.t()) :: {:ok, module()} | :error
  def module_for("capabilities"), do: {:ok, GraphlawEx.Capability.Capabilities}
  def module_for("sniff"), do: {:ok, GraphlawEx.Capability.Sniff}
  def module_for("parse"), do: {:ok, GraphlawEx.Capability.Parse}
  def module_for("convert"), do: {:ok, GraphlawEx.Capability.Convert}
  def module_for("canonical"), do: {:ok, GraphlawEx.Capability.Canonical}
  def module_for("sparql"), do: {:ok, GraphlawEx.Capability.Sparql}
  def module_for("shacl"), do: {:ok, GraphlawEx.Capability.Shacl}
  def module_for("shex"), do: {:ok, GraphlawEx.Capability.Shex}
  def module_for("n3"), do: {:ok, GraphlawEx.Capability.N3}
  def module_for("entail"), do: {:ok, GraphlawEx.Capability.Entail}
  def module_for("datalog"), do: {:ok, GraphlawEx.Capability.Datalog}
  def module_for("hooks"), do: {:ok, GraphlawEx.Capability.Hooks}
  def module_for("law"), do: {:ok, GraphlawEx.Capability.Law}
  def module_for("policy"), do: {:ok, GraphlawEx.Capability.Policy}
  def module_for(_name), do: :error

  @doc "All dialects in global order (RDF dialects first, then the others)."
  @spec dialects() :: [dialect()]
  def dialects, do: @dialects

  @doc "RDF dialect names in registry order."
  @spec rdf_dialects() :: [String.t()]
  def rdf_dialects, do: for(d <- @dialects, d.kind == "rdf", do: d.name)

  @doc "Non-RDF dialect names in registry order."
  @spec other_dialects() :: [String.t()]
  def other_dialects, do: for(d <- @dialects, d.kind == "other", do: d.name)

  @doc "The steps of the `law` operation in registry order, keyed by wire name (`\"record-receipts\"`)."
  @spec law_steps() :: [law_step()]
  def law_steps, do: @law_steps

  @doc "The engine refusal detail codes (`details.code` wire values) in registry order."
  @spec refusal_codes() :: [refusal_code()]
  def refusal_codes, do: @refusal_codes

  @doc "The engine resource limits as an atom-keyed map."
  @spec limits() :: %{optional(atom()) => non_neg_integer()}
  def limits, do: @limits

  @doc "A closed registry vocabulary by name (`\"regimes\"`, `\"engines\"`, ...); `[]` when unknown."
  @spec vocabulary(String.t()) :: [String.t()]
  def vocabulary(name) when is_binary(name), do: Map.get(@vocabulary, name, [])

  @doc "The entailment regimes the `entail` operation accepts."
  @spec regimes() :: [String.t()]
  def regimes, do: vocabulary("regimes")

  @doc "The engines a `sniff` response may name."
  @spec engines() :: [String.t()]
  def engines, do: vocabulary("engines")

  @doc "The engine refusal kinds."
  @spec refusal_kinds() :: [String.t()]
  def refusal_kinds, do: vocabulary("refusal_kinds")

  @doc "The lease ceilings."
  @spec lease_ceilings() :: [String.t()]
  def lease_ceilings, do: vocabulary("lease_ceilings")

  @doc "The lease refusal reasons."
  @spec lease_reasons() :: [String.t()]
  def lease_reasons, do: vocabulary("lease_reasons")

  @doc "The receipt refusal reasons."
  @spec receipt_reasons() :: [String.t()]
  def receipt_reasons, do: vocabulary("receipt_reasons")

  @doc "The `policy` operation refusal kinds."
  @spec policy_refusal_kinds() :: [String.t()]
  def policy_refusal_kinds, do: vocabulary("policy_refusal_kinds")
end
